// Battle order follows the selected lead, while the saved party order remains intact.
// The battle engine moves fainted members behind healthy ones; persist its actual lead.
function createAdventureCombat(s:any,mons:Map<string,any>,foes:any[],options:any={}){
 const ids=[s.activeId,...s.teamIds.filter((id:string)=>id!==s.activeId)];
 const team=ids.map((id:string)=>mons.get(id));
 const combat=createCombat(team,foes,options);combat.adventureMoveCount=0;combat.adventureBattleBase=adventureBattleBase([team,foes]);
 const lead=combat.teams[0][combat.requests[0].active];if(lead)s.activeId=lead.boxId;
 return combat;
}
async function read(id:string,extraIds:string[]=[],all=true){const row=await db().prepare('SELECT state,revision FROM worlds WHERE user_id=?').bind(id).first<any>();const raw=row?JSON.parse(row.state):null;const wanted=[...new Set([...(raw?.teamIds||[raw?.activeId]),raw?.activeId,raw?.zaTradeHeracrossId,...(Array.isArray(raw?.adventurePendingMoves)?raw.adventurePendingMoves.map((entry:any)=>entry?.boxId):[]),...extraIds].filter((v:any)=>typeof v==='string'&&v.length<=100))];const box=all?await db().prepare('SELECT id,data,origin FROM pokemon_box WHERE user_id=? ORDER BY created_at,id').bind(id).all<any>():wanted.length?await db().prepare(`SELECT id,data,origin FROM pokemon_box WHERE user_id=? AND id IN (${wanted.map(()=>'?').join(',')}) ORDER BY created_at,id`).bind(id,...wanted).all<any>():{results:[]};const mons=new Map<string,any>(box.results.map((r:any)=>[r.id,{...normalizeStoredPokemon({...JSON.parse(r.data),boxId:r.id}),boxId:r.id,origin:r.origin}]));const state=row?JSON.parse(row.state):null;if(state?.zaTradedPikachuId)mons.delete(state.zaTradedPikachuId);if(state){if(state.adventureCatchWindow&&(!state.adventureCatchWindow.foe||state.adventureCatchWindow.revision!==row.revision||state.combat))delete state.adventureCatchWindow;state.area??=0;state.regionId??=1;state.badges??=[];state.league??=0;state.teamIds=[...new Set<string>(state.teamIds||[state.activeId])].filter(x=>mons.has(x)).slice(0,6);if(!state.teamIds.length&&mons.has(state.activeId))state.teamIds=[state.activeId];if(!state.teamIds.length&&mons.has(state.zaTradeHeracrossId))state.teamIds=[state.zaTradeHeracrossId];if(!state.teamIds.includes(state.activeId))state.activeId=state.teamIds[0];state.log??=[];if(state.encounter&&!state.combat){const mon=mons.get(state.activeId);if(mon)state.combat=createAdventureCombat(state,mons,[state.encounter]);state.battle=null;}}if(state?.district==='lumiose-zone19')state.zaZone19Period=gameTime().period;if(state?.district==='lumiose-zone15')state.zaZone15Period=gameTime().period;if(state?.district==='lumiose-zone13')state.zaZone13Period=gameTime().period;if(state?.district==='lumiose-zone14'){const time=gameTime();state.zaZone14Period=time.period;state.weather=['water','poison'].includes(AREAS[state.area]?.biome)&&time.hour%2===0?'rain':'';}restoreAdventurePosition(state,row?.revision);normalizeField(state);return {row,state,mons};}
async function unionMembers(host:string,area:number,locationId=0){if(!host)return [];const rows=await db().prepare("SELECT w.user_id,w.state,p.nickname FROM worlds w JOIN profiles p ON p.user_id=w.user_id WHERE json_extract(w.state,'$.unionHost')=? AND w.updated_at>? LIMIT 5").bind(host,Date.now()-120000).all<any>();return rows.results.map((r:any)=>({...JSON.parse(r.state),nickname:r.nickname})).filter((s:any)=>s.area===area&&(s.locationId||0)===locationId).map((s:any)=>({name:s.nickname,x:s.x,y:s.y}));}
